from datetime import date, datetime, timedelta

import calendar_import
import categories
import config
import importers
import models
import uniclubs_database


EVENT_PREFIX = 'uniclubs:'
SERIES_PREFIX = 'uniclubs-series:'
CLUB_PREFIX = 'uniclubs-club:'
EVENT_QUERY = '''SELECT e.*, c.name AS club_name, c.external_id AS club_external_id
    FROM events e INNER JOIN clubs c ON c.id=e.club_id'''
EVENT_BY_ID_QUERY = EVENT_QUERY + ' WHERE e.external_id=?'


def is_catalog_id(value):
    """Return whether a value is a nonempty source-namespaced UniClubs event identity."""
    if not isinstance(value, str) or not value.startswith(EVENT_PREFIX):
        return False
    suffix = value[len(EVENT_PREFIX):]
    return bool(suffix) and suffix == suffix.strip()


def public_id(identifier):
    """Namespace a source event ID so it cannot collide with legacy integer event IDs."""
    if (not isinstance(identifier, str) or not identifier.strip()
            or identifier != identifier.strip()):
        raise ValueError('A nonempty UniClubs source identifier is required.')
    return EVENT_PREFIX + identifier


def external_id(event_id):
    """Recover the source event ID from its validated application namespace."""
    if not is_catalog_id(event_id):
        raise ValueError('A namespaced UniClubs event ID is required.')
    return event_id[len(EVENT_PREFIX):]


def _local_time(value):
    """Validate original UTC text and use the shared calendar boundary for Zurich time."""
    canonical = uniclubs_database.normalize_utc_time(value)
    instant = datetime.fromisoformat(canonical.replace('Z', '+00:00'))
    return calendar_import.to_local_naive(instant)


def _boundaries(start, end):
    """Validate a positive date or naive Zurich datetime query interval."""
    values = []
    for value in (start, end):
        if isinstance(value, date) and not isinstance(value, datetime):
            value = datetime.combine(value, datetime.min.time())
        if not isinstance(value, datetime) or value.tzinfo is not None:
            raise ValueError('Catalog boundaries must be dates or naive Zurich datetimes.')
        values.append(value)
    if values[1] <= values[0]:
        raise ValueError('The catalog range must end after its start.')
    return values


def _times(row):
    """Prepare a display interval without writing an estimated end back to the source catalog."""
    start = _local_time(row['start_utc'])
    estimated = row['end_utc'] is None
    end = (start + timedelta(minutes=config.DEFAULT_DURATION_MINUTES)
           if estimated else _local_time(row['end_utc']))
    if end <= start:
        raise ValueError('The source interval cannot be represented as a Zurich calendar interval.')
    return start, end, estimated


def _status(row):
    """Map publication and registration separately without inventing a source cancellation."""
    publication = row['publication_status'].lower()
    registration = row['availability_state'].lower()
    cancelled = publication in ('cancelled', 'canceled')
    if cancelled or row['source_missing']:
        return 'closed', cancelled
    if registration == 'full':
        return 'full', False
    if registration in ('sales_closed', 'sales_not_started', 'closed'):
        return 'closed', False
    if row['requires_membership']:
        return 'members_only', False
    return 'open', False


class CatalogEvent(models.ClubEvent):
    """Represent one public catalog record with collision-free IDs and source freshness flags."""

    def __init__(self, row, taxonomy):
        """Build a normal domain event while keeping source metadata explicitly available."""
        start, end, estimated = _times(row)
        event_type = row['event_type'].title()
        direction, bundle_key = categories.assign_category(
            {'source': 'uniclubs', 'title': row['title'], 'event_type': event_type}, taxonomy)
        bundle = next(item for item in taxonomy['bundles'] if item['key'] == bundle_key)
        status, cancelled = _status(row)
        super().__init__(
            event_id=public_id(row['external_id']),
            series_id=SERIES_PREFIX + row['external_id'], title=row['title'],
            start=start, end=end, location=row['location'],
            location_type=importers.classify_location(row['location']),
            direction_key=direction, bundle_key=bundle_key, bundle_name=bundle['name'],
            organizer=row['club_name'], event_type=event_type, source_url=row['source_url'],
            price=None, members_only=bool(row['requires_membership']),
            end_is_estimated=estimated, status=status,
            club_id=CLUB_PREFIX + row['club_external_id'], club_name=row['club_name'])
        self.source_missing = bool(row['source_missing'])
        self.source_cancelled = cancelled
        self.registration_state = row['availability_state']
        self.publication_status = row['publication_status']
        self.can_confirm = (not self.source_missing and not cancelled and not estimated
                            and not self.is_multi_day() and status not in config.HIDDEN_STATUSES
                            and row['publication_status'].lower() == 'published'
                            and row['availability_state'].lower() in ('open', 'limited'))

    def display_tags(self):
        """Label missing sources, explicit cancellation and registration availability distinctly."""
        tags = super().display_tags()
        if self.source_cancelled:
            tags.append('Cancelled by organizer')
        if self.source_missing:
            tags.append('Not in latest source snapshot')
        labels = {'sales_closed': 'Registration closed', 'full': 'Full',
                  'sales_not_started': 'Registration not open', 'limited': 'Limited availability'}
        if self.registration_state in labels:
            tags.append(labels[self.registration_state])
        if self.is_multi_day():
            tags.append('Multi-day schedule — check original page')
        return tags


def events_between(connection, start, end):
    """Return overlapping source events; omit individually invalid local intervals.

    UTC intervals crossing the repeated autumn hour can be positive yet nonpositive as naive
    local wall time. Such a record cannot be placed by the existing calendar model and is omitted
    without making the entire week unavailable. get_event raises ValueError for that record.
    """
    start, end = _boundaries(start, end)
    taxonomy = categories.load_taxonomy()
    events = []
    for row in connection.execute(EVENT_QUERY).fetchall():
        try:
            event = CatalogEvent(row, taxonomy)
        except (ValueError, TypeError, OverflowError):
            continue
        if event.start < end and event.end > start:
            events.append(event)
    return sorted(events, key=lambda event: (event.start, event.event_id))


def get_event(connection, event_id):
    """Return one source-aware event, None if absent, or ValueError for invalid source time."""
    identifier = external_id(event_id)
    row = connection.execute(EVENT_BY_ID_QUERY, (identifier,)).fetchone()
    return CatalogEvent(row, categories.load_taxonomy()) if row is not None else None


def date_bounds(connection):
    """Return the earliest/latest valid local start dates, or (None, None)."""
    days = []
    for row in connection.execute(EVENT_QUERY).fetchall():
        try:
            start, _, _ = _times(row)
            days.append(start.date())
        except (ValueError, TypeError, OverflowError):
            continue
    return (min(days), max(days)) if days else (None, None)
